1018	
1019	  /// Sets the alignment attribute of the Function.
1020	  ///
1021	  /// This method will be deprecated as the alignment property should always be
1022	  /// defined.
1023	  void setAlignment(MaybeAlign Align) { GlobalObject::setAlignment(Align); }
1024	
