1107	  void setFramePointer(FramePointerKind Kind);
1108	
1109	  /// Get/set what kind of stack protector guard to use.
1110	  StringRef getStackProtectorGuard() const;
1111	  void setStackProtectorGuard(StringRef Kind);
1112	
1113	  /// Get/set which register to use as the stack protector guard register. The
1114	  /// empty string is equivalent to "global". Other values may be "tls" or
1115	  /// "sysreg".
1116	  StringRef getStackProtectorGuardReg() const;
1117	  void setStackProtectorGuardReg(StringRef Reg);
1118	
1119	  /// Get/set a symbol to use as the stack protector guard.
1120	  StringRef getStackProtectorGuardSymbol() const;
1121	  void setStackProtectorGuardSymbol(StringRef Symbol);
1122	
1123	  /// Get/set what offset from the stack protector to use.
1124	  int getStackProtectorGuardOffset() const;
1125	  void setStackProtectorGuardOffset(int Offset);
1126	
1127	  /// Get/set the width in memory of the stack protector guard value.
1128	  std::optional<unsigned> getStackProtectorGuardValueWidth() const;
1129	  void setStackProtectorGuardValueWidth(unsigned Width);
1130	
1131	  // Get/set flag indicating whether to emit a __stack_protector_loc section.
1132	  bool hasStackProtectorGuardRecord() const;
1133	  void setStackProtectorGuardRecord(bool Flag);
1134	
1135	  /// Get/set the stack alignment overridden from the default.
1136	  unsigned getOverrideStackAlignment() const;
1137	  void setOverrideStackAlignment(unsigned Align);
1138	
1139	  unsigned getMaxTLSAlignment() const;
1140	
1141	  /// @name Utility functions for querying and setting the build SDK version
1142	  /// @{
1143	
1144	  /// Attach a build SDK version metadata to this module.
1145	  void setSDKVersion(const VersionTuple &V);
1146	
1147	  /// Get the build SDK version metadata.
1148	  ///
1149	  /// An empty version is returned if no such metadata is attached.
1150	  VersionTuple getSDKVersion() const;
1151	  /// @}
1152	
1153	  /// Take ownership of the given memory buffer.
1154	  void setOwnedMemoryBuffer(std::unique_ptr<MemoryBuffer> MB);
1155	
1156	  /// Set the partial sample profile ratio in the profile summary module flag,
1157	  /// if applicable.
1158	  void setPartialSampleProfileRatio(const ModuleSummaryIndex &Index);
1159	
1160	  /// Get the target variant triple which is a string describing a variant of
1161	  /// the target host platform. For example, Mac Catalyst can be a variant
1162	  /// target triple for a macOS target.
1163	  /// @returns a string containing the target variant triple.
1164	  StringRef getDarwinTargetVariantTriple() const;
1165	
1166	  /// Set the target variant triple which is a string describing a variant of
1167	  /// the target host platform.
1168	  void setDarwinTargetVariantTriple(StringRef T);
1169	
1170	  /// Get the target variant version build SDK version metadata.
1171	  ///
1172	  /// An empty version is returned if no such metadata is attached.
1173	  VersionTuple getDarwinTargetVariantSDKVersion() const;
1174	
1175	  /// Set the target variant version build SDK version metadata.
1176	  void setDarwinTargetVariantSDKVersion(VersionTuple Version);
1177	
1178	  /// Returns target-abi from MDString, null if target-abi is absent.
1179	  StringRef getTargetABIFromMD();
1180	
1181	  /// Get how unwind information should be generated for x64 Windows.
1182	  WinX64EHUnwindMode getWinX64EHUnwindMode() const;
1183	
1184	  /// Gets the Control Flow Guard mode.
1185	  ControlFlowGuardMode getControlFlowGuardMode() const;
1186	};
1187	
1188	/// Given "llvm.used" or "llvm.compiler.used" as a global name, collect the
1189	/// initializer elements of that global in a SmallVector and return the global
1190	/// itself.
1191	LLVM_ABI GlobalVariable *
1192	collectUsedGlobalVariables(const Module &M, SmallVectorImpl<GlobalValue *> &Vec,
1193	                           bool CompilerUsed);
1194	
1195	/// An raw_ostream inserter for modules.
1196	inline raw_ostream &operator<<(raw_ostream &O, const Module &M) {
1197	  M.print(O, nullptr);
1198	  return O;
1199	}
1200	
1201	// Create wrappers for C Binding types (see CBindingWrapping.h).
1202	DEFINE_SIMPLE_CONVERSION_FUNCTIONS(Module, LLVMModuleRef)
1203	
1204	/* LLVMModuleProviderRef exists for historical reasons, but now just holds a
